insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 0, 'GIS数据源可以根据获取方式或表现形式进行分类，以下属于按表现形式分类的是？', '地图数据', '遥感影像数据', '多媒体数据', '实测数据', 'C', 'A选项：地图数据是根据数据获取方式分类的GIS主要数据源之一 。 B选项：遥感影像数据同样属于按获取方式分类的数据源类别 。 C选项：按照数据的表现形式，数据可分为数字化数据、多媒体数据及文本资料数据 。 D选项：实测数据属于野外通过实验或实地测量直接获取的数据，也是按获取方式分类的 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 1, '在应用地图数据作为GIS数据源时，通常需要注意的地图缺陷不包括哪一项？', '存储介质存在变形缺陷', '现势性较差', '投影转换的复杂性', '地图无法被分解为基本要素', 'D', 'A选项：由于纸质地图在不同存放条件下存在不同程度的变形，应用时需进行纠正，这是其固有缺陷 。 B选项：传统地图更新周期较长，现势性较差，不能完全满足实际需要 。 C选项：使用不同投影的地图数据交流前，必须进行地图投影的转换，这是一个需要注意的问题 。 D选项：将地图内容分解为点、线和面三类基本要素并进行编码，是GIS利用地图的常规组织方式，这并非缺陷 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 2, '航空摄影测量中，为满足立体覆盖的要求，航线上任意相邻两张像片的航向重叠度不应少于多少？', '30%', '55%', '60%', '100%', 'B', 'A选项：30%是相邻航线上的两张相邻像片的旁向重叠度标准 。 B选项：航测规定飞机沿一条航线飞行时，相机拍摄的任意相邻两张像片的航向重叠度不少于55% 。 C选项：规定下限明确为55%，而非60% 。 D选项：100%的重叠度不符合摄影测量的常规立体覆盖原则 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 3, '倾斜摄影测量技术相较于传统正射影像，具有什么突破性特点？', '只能从垂直角度拍摄', '仅使用单台传感器采集', '同时从一个垂直和四个倾斜等五个角度采集影像', '无法真实反映地物外观高度', 'C', 'A选项：传统正射影像才存在只能垂直拍摄的局限性 。 B选项：倾斜摄影是在同一飞行平台上搭载多台传感器进行数据采集 。 C选项：该技术能够同时从一个垂直、四个倾斜等五个不同的角度采集影像，从而提供更丰富的地理信息 。 D选项：该技术能生成直观反映地物外观、位置、高度等属性的数据成果 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 4, '扫描地图获得栅格数据时，不属于地图内容的斑点污渍被称为？', '悬挂节点', '伪节点', '中间色调', '噪声', 'D', 'A选项：悬挂节点是指矢量数据拓扑编辑中节点只与一条线相连的几何错误 。 B选项：伪节点是指由于一条线没有一次录入完毕导致的矢量数据错误 。 C选项：中间色调像元是扫描中产生的另一类问题，需通过选择合适的阈值来处理 。 D选项：噪声是指不属于地图内容的斑点污渍和其他模糊不清的物体形成的像元灰度值 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 5, '国家资源与环境信息系统规范将数据分为三大类，“基础地质数据”属于哪一类？', '社会环境数据', '自然环境数据', '资源与能源数据', '互联网数据', 'B', 'A选项：社会环境数据主要包括城市与人口、交通网、行政区划等内容 。 B选项：自然环境数据包括地形数据、海岸及海域数据、水系及流域数据、基础地质数据五类 。 C选项：资源与能源数据涵盖土地资源、气候、矿产资源等数据类型 。 D选项：互联网数据是通过网络爬虫等方式获取的大数据，不属于该传统的分类项 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 6, '在GIS属性数据编码方法中，能明确表示出分类对象的类别且代码结构有严格隶属关系的方法是？', '游程长度编码法', '多源分类编码法', '层次分类编码法', '四叉树法', 'C', 'A选项：游程长度编码是用于栅格数据空间压缩的一种技术，与属性分类无关 。 B选项：多源分类编码法（独立分类编码法）的各位数字代码之间并没有隶属关系 。 C选项：层次分类编码法按照从属和层次关系排列，其优点是能明确表示类别，代码结构具有严格的隶属关系 。 D选项：四叉树法也是一种栅格数据的空间压缩编码技术 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 7, '多源分类编码法（独立分类编码法）的主要特点是？', '各位数字代码之间没有隶属关系', '代码间具有严格的树状从属关系', '只能用于简单的属性描述', '信息载量通常较小', 'A', 'A选项：多源分类编码法是根据不同的分类依据分别进行编码，各位数字代码之间没有隶属关系 。 B选项：具有严格树状从属关系的是层次分类编码法 。 C选项：它通过综合多种分类依据，适用于复杂或特定的专题目标描述 。 D选项：该编码方法通常具有较大的信息载量，有利于对空间信息进行综合分析 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 8, '在图形数据数字化采集中，如果一条线没有一次录入完毕，使完整的线变成两段，会产生哪种错误？', '碎屑多边形', '悬挂节点', '伪节点', '不正规多边形', 'C', 'A选项：碎屑多边形是由于重复录入同一条线且位置不完全一致而引发的 。 B选项：悬挂节点是指图形中一个节点仅与一条线相连接的错误情况 。 C选项：伪节点（Pseudo Node）正是由于一条线分多次录入导致的断点，使本来完整的线变成两段 。 D选项：不正规的多边形是由于输入点次序倒置或位置不准确导致的 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 9, '空间数据编辑中，碎屑多边形（Sliver Polygon）通常产生的原因是？', '录入线时点的次序倒置', '节点不重合', '前后两次录入同一条线的位置不可能完全一致', '一条线被分作多次录入', 'C', 'A选项：点次序倒置会引起不正规的多边形，而非碎屑多边形 。 B选项：节点不重合属于悬挂节点或导致多边形不封闭的原因 。 C选项：由于前后两次录入同一条线的位置不可能完全一致，或者使用不同比例尺数据更新时，就会产生碎屑多边形 。 D选项：多次录入一条线会导致伪节点错误 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 10, '在多边形拓扑关系的建立过程中，为解决因数字化误差导致原本同一节点坐标不一致的问题，应首先进行的操作是？', '生成嵌套内岛', '结点匹配（snap）', '进行多边形包含分析', '按方位角排序', 'B', 'A选项：处理内岛属于建立多边形以后的嵌套分析步骤 。 B选项：结点匹配是以端点为圆心按给定容差产生搜索圆，将落入圆内的端点坐标取平均值作为同一结点，这是拓扑建立的第一步 。 C选项：多边形包含分析用于识别多边形的嵌套关系，不是解决节点不一致的方法 。 D选项：按方位角排序是在结点匹配完成后，为追踪多边形边界而进行的前置准备 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 11, '在建立多边形拓扑的计算中，方位角是指从x轴按什么方向量至该弧段上相邻顶点的连线的夹角？', '顺时针方向', '逆时针方向', '正北方向', '正东方向', 'B', 'A选项：顺时针方向是算法搜索多边形闭合边界时的追踪方向 。 B选项：定义明确指出，方位角是指从x轴按逆时针方向量至结点与它相邻弧段上顶点的连线的夹角 。 C选项：并非由正北方向起量 。 D选项：是从x轴（即正东方向）按逆时针量度，而非向东向量度 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 12, '计算机自动生成多边形拓扑关系时，算法追踪闭合边界的默认搜索方向是？', '顺时针方向', '逆时针方向', '从外向内方向', '按长度最短方向', 'A', 'A选项：算法规定，从弧段文件中得到起始弧段后，以顺时针方向为搜索方向追踪下一条待连接的弧段，直至闭合 。 B选项：逆时针是计算方位角的规定方向以及记录内多边形的排序方向 。 C选项：该算法是基于弧段拓扑节点的追踪，并非内外向扩散 。 D选项：算法是依据结点处关联弧段的方位角大小顺序，寻找后续弧段，而非按长度 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 13, '当地形图的实际尺寸发生几何变形需要纠正时，最常用的方法是？', '双三次卷积法', '射线法', '四点纠正法或逐网格纠正法', '像元平滑法', 'C', 'A选项：双三次卷积法是用于栅格数据重采样的插值算法 。 B选项：射线法是矢量向栅格转换中填充多边形属性的方法 。 C选项：对地形图的几何纠正，一般利用四个图廓控制点进行四点纠正法，若精度不足则采用逐方里网的逐网格纠正法 。 D选项：像元平滑法不属于系统纠正地形图宏观变形的专业模型方法 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 14, '在进行空间坐标系下的几何仿射变换时，最少需要几个位移关联点？', '1个', '2个', '3个', '4个', 'C', 'A、B选项：仿射变换包含平移、旋转、两个方向不同的缩放等参数，1或2个点解算不出变换矩阵 。 C选项：仿射变换可以将正方形变为平行四边形，计算其系数最少需要三个独立的位移关联点 。 D选项：4个点可以用于更复杂变换（如双线性、投影变换或冗余平差），但“最少”条件是3个 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 15, '以下哪一项不属于二维空间相似变换的基本操作？', '平移', '旋转', '缩放', '橡皮拉伸', 'D', 'A选项：平移是将图形的一部分或整体移动到另一个位置，属于相似变换基本操作 。 B选项：旋转常用于地图投影变换或图形摆正，属于相似变换 。 C选项：缩放用于输出大小不同的图形，属于相似变换 。 D选项：橡皮拉伸是一种通过局部坐标几何纠正来修正特定缺陷的弹性变换方法，不保证全局形状相似，故不属于单纯的相似变换 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 16, '在栅格数据重采样中，直接取与目标点位置最近像元的值作为该点采样值的方法是？', '最邻近像元法', '双线性插值法', '双三次卷积法', '样条函数内插法', 'A', 'A选项：最邻近像元法就是直接取与待求点位置最近像元N的值作为该点的采样值 。 B选项：双线性插值法是根据最邻近的四个数据点确定一个双线性多项式求值 。 C选项：双三次卷积法利用周边更多节点分块构造三次多项式曲面 。 D选项：样条函数内插要求n次连续导数，是一种复杂的平滑插值方法 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 17, '栅格重采样中，能够精确保留局部微特征并具有良好视觉平滑效果的三次曲面插值方法是？', '最邻近像元法', '游程长度编码法', '双三次卷积法', '中心轴线提取法', 'C', 'A选项：最邻近法会产生锯齿效果，无法保证微特征的平滑 。 B选项：游程长度编码是减少栅格数据量的压缩方法，不是重采样插值法 。 C选项：双三次卷积法采用三次曲面描述内插值，能够精确通过已知点，保留局部微特征并在视觉上令人满意 。 D选项：这属于矢量数据压缩和处理的方法 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 18, '从扫描图进行栅格向矢量转换的过程中，哪一步骤是专门为了减少坐标冗余并进行曲线平滑的？', '边界提取', '二值化', '细化', '去除多余点及曲线圆滑', 'D', 'A选项：边界提取是从面状栅格中提取外轮廓线的步骤 。 B选项：二值化是将灰度图像转为黑白两色以供后续跟踪处理的步骤 。 C选项：细化是将占据多个栅格宽度的线划变细为单像素宽度的步骤 。 D选项：由于搜索是逐个栅格进行的，会产生多余节点，因此后续必须去除多余点并使用插补算法（如线性叠代法）进行曲线圆滑以减少冗余 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 19, '将矢量多边形数据转换为栅格数据时，用于多边形内部网格填充的常用算法是？', '最邻近像元法', '内部点扩散法', '垂距法', '分裂法', 'B', 'A选项：属于栅格影像的重采样插值法 。 B选项：将矢量面域向栅格转换通常称为多边形填充，常用算法有内部点扩散法、射线法、扫描线法等 。 C选项：垂距法是矢量数据坐标点的压缩去重方法 。 D选项：分裂法（Douglas-Peucker法）也是矢量线数据的一种压缩方法 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 20, '图形拼接时，对于相邻图幅相接处的具有相同属性的两个多边形图斑，正确的处理方式是？', '必须保留双方原始图幅的边界线', '随机删除其中一个多边形', '消除它们之间的公共边界，并对共同属性进行合并', '将接缝区域单独建立一个新的属性代码', 'C', 'A选项：保留原始边界会使一个完整的自然地物（如图斑）被人为从逻辑上割裂，导致逻辑错误 。 B选项：随机删除会丢失真实的地理信息覆盖范围 。 C选项：应将相同属性的两个或多个相邻图斑组合成一个图斑，即通过线段链表技术消除公共边界，并对属性进行合并 。 D选项：该操作违背了反映真实地理实体的基本原则 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 21, '在矢量数据压缩中，试图保持曲线的总体走向，通过递归地比较点到直线的垂足距离与规定限差来筛选点的方法是？', '间隔取点法', '垂距法', '偏角法', '分裂法（Douglas-Peucker法）', 'D', 'A选项：间隔取点法是简单地按固定距离或固定节点数进行跳跃式取点 。 B、C选项：垂距法和偏角法仅按单次计算的限差过滤点，缺乏全局曲线保持能力 。 D选项：分裂法（Douglas-Peucker法）通过连接曲线首末两端形成直线，保留最大垂足距离的点将曲线递归分段，从而在压缩数据时很好地保持了曲线原始走向 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 22, '在空间数据质量评估中，表示量测数据与其“真值”之间客观差异的概念是？', '精密度（Precision）', '误差（Error）', '偏差（Bias）', '逻辑一致性', 'B', 'A选项：精密度是指在对某个量的多次量测中，各量测值相互之间的离散程度 。 B选项：误差明确表示为数据与其真值之间的差异，是一个客观确定的量测偏离数值 。 C选项：偏差是基于一个面向全体量测值的统计模型，通常以平均误差来描述 。 D选项：逻辑一致性是指数据内部的结构和关系的规范依附度 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 23, '假设在一组重复的测量数据中，所有数值彼此之间非常接近，但是它们的平均值距离真实的物理数值非常远。这组数据可以被描述为？', '准确度高，精密度低', '准确度低，精密度高', '准确度高，精密度高', '准确度低，精密度低', 'B', 'A选项：精密度低意味着数值应该非常分散，与题意不符 。 B选项：数值彼此非常接近代表它的精密度高（离散程度小）；而平均值离真实数值（真值）远，代表它的准确度低 。 C选项：由于偏离真值远，不能称为准确度高 。 D选项：因为测量值集中，所以精密度并不低 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 24, '在评估空间数据质量时，检测数据集中“是否包含多余数据”和“是否缺少应该包含的数据”，属于对哪一类质量指标的评价？', '完备性', '位置准确度', '逻辑一致性', '专题准确度', 'A', 'A选项：完备性评估要素、要素属性和要素关系的存在和缺失，其包含两个具体指标：多余（数据集中多余的数据）和遗漏（数据集中缺少的数据） 。 B选项：位置准确度评估的是坐标位置的绝对或相对精度 。 C选项：逻辑一致性评估数据结构规则及拓扑的匹配程度 。 D选项：专题准确度是对定量或定性属性的分类正确性评价 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 25, '空间数据质量评价方法中，对生产出的最终数据集通过全面检测或抽样检测方式进行直接测量的评价方法称为？', '间接评价法', '预估度量法', '直接评价法', '外部知识推理法', 'C', 'A选项：间接评价法是基于来源、生产方法等间接信息估算质量的方法 。 B选项：预估度量法是间接评价法的别称 。 C选项：直接评价法（也称验收度量）是对数据集直接通过全面检测或抽样检测的方式进行评价的方法 。 D选项：外部知识推理是属于间接评价法利用外部信息的方式 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 26, '关于GIS中误差的产生和误差传播，以下说法正确的是？', '误差仅仅在数据输入时产生，之后不会增加', 'GIS系统的内部数据处理和空间分析过程不会带来新的误差', '空间数据的误差源蕴涵在整个GIS运行的每个环节，并随系统的运行不断传播', '借助完善的软件系统，GIS中的误差都可以被完全消除', 'C', 'A选项：除数据输入外，原始数据源自身以及后续分析都有误差 。 B选项：GIS对数据库中数据的处理和分析过程同样会产生误差，并传播到结果中 。 C选项：空间数据的误差源蕴涵在整个GIS运行的每个环节，并且往往会随系统的运行不断传播甚至累积 。 D选项：误差分析相当复杂，甚至在某些环节没有任何方式可对其进行消除或分析，无法完全消除 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 27, '为了实现不同系统间的数据格式转换和共享，目前对大多数普通用户而言，最具备可操作性和现实性的模式是？', '建立深度的语义数据模型', '外部数据交换模式', '直接数据访问模式', '构建庞大的空间数据共享平台模式', 'B', 'A选项：语义层转换是复杂的深层次转换方案 。 B选项：与其他高级模式相比，外部数据交换模式（利用交换文件如DXF、MIF等或自定义文本介质）在具体应用中更具可操作性和现实性，与现实的技术、资金条件更相符 。 C、D选项：这两种模式提供了较为理想的共享模式，但技术门槛和系统构建成本很高，非普通用户首选 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 28, '元数据（Metadata）在空间数据库中具有极其重要的作用，以下关于它的描述错误的是？', '它是关于数据的描述数据', '能够为用户提供丰富的引导、分析和索引信息', '它的主要作用是彻底取代原始空间数据库的坐标存储', '它可以记录数据处理过程中质量的变化，用于数据质量控制', 'C', 'A选项：元数据定义为关于数据的描述数据 。 B选项：元数据提供丰富的引导信息，帮助用户了解和分析数据 。 C选项：元数据主要用于记录数据特征、描述坐标系系统、质量等信息供查询和管理，它是辅助信息的集合，并不能彻底取代底层承载坐标与几何实体的物理数据库系统 。 D选项：元数据记录了数据质量的变化，通过跟踪元数据可以进行空间数据质量控制 。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-6', 29, '从数据集成的角度来看，空间数据库系统包含的子数据库中，存放被更新下来的旧版本成果数据的数据库是？', '成果管理数据库', '工作数据库', '历史数据库', '临时数据库', 'C', 'A选项：成果管理数据库是用于向用户提供现势性最好的成果数据的库 。 B选项：工作运行数据库是为了实现对成果数据在线检索、分析应用而建立的 。 C选项：被更新下来的成果数据专门存放在历史数据库中 。 D选项：不属于上述空间库按管理属性区分的三个主要核心库之列', datetime('now'));
